{"implementation":"def solve(case):
    nodes = list(case.get("nodes", []))
    required = set(case.get("required_symbols", []))

    by_id = {}
    children = {}
    for node in nodes:
        node_id = node.get("id")
        by_id[node_id] = node
        parent = node.get("parent")
        children.setdefault(parent, []).append(node_id)
        children.setdefault(node_id, children.get(node_id, []))

    needed = set()

    def mark_ancestors(node_id):
        while node_id is not None and node_id not in needed:
            needed.add(node_id)
            node = by_id.get(node_id)
            if node is None:
                break
            node_id = node.get("parent")

    for node in nodes:
        if not node.get("removable", False) or node.get("symbol") in required:
            mark_ancestors(node.get("id"))

    retained = []
    removed = []
    for node in nodes:
        node_id = node.get("id")
        if node_id in needed:
            retained.append(node_id)
        else:
            removed.append(node_id)

    return {"removed_node_ids": removed, "retained_node_ids": retained}
"}
